styles:
.ro-box {
      resize: both;
      overflow: auto;
      box-sizing: border-box;
      min-width: 140px;
      min-height: 90px;
      max-width: 100%;
      width: 220px;
      height: 120px;
      padding: 1rem;
      border: 1px dashed var(--iswc-border);
      border-radius: var(--iswc-radius, 0.5em);
      background:
        repeating-linear-gradient(45deg,
          color-mix(in srgb, var(--iswc-border) 35%, transparent) 0 8px,
          transparent 8px 16px),
        var(--iswc-bg-elev);
      color: var(--iswc-text);
      font-size: 0.9rem;
      line-height: 1.4;
    }
    .ro-meta {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.75rem 1.25rem;
      margin-top: 0.75rem;
      font-size: 0.9rem;
      color: var(--iswc-text-soft);
    }
    .ro-size {
      font-variant-numeric: tabular-nums;
      font-weight: 600;
      color: var(--iswc-text);
    }
    .ro-status {
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      padding: 0.2em 0.55em;
      border-radius: 999px;
      background: var(--iswc-brand-soft, color-mix(in srgb, var(--iswc-color-brand) 18%, transparent));
      color: var(--iswc-brand-text, var(--iswc-color-brand));
    }
    .ro-status.iswc-off {
      background: var(--iswc-control-bg);
      color: var(--iswc-text-dim);
    }
    .ro-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      align-items: center;
      margin-bottom: 0.75rem;
    }
    .log .type-res { color: #74c0fc; }
    .log .type-off { color: #ffa8a8; }
